def close(ids, details, dependencies, refs=(), outcome='complete proof checked under its stated hypotheses; the specified dependency checks are closed'):
    for sid in ids.split('|'):
        row = by_id[sid]
        event = {'source_id': sid, 'reader': META, 'event': 'dependency-closure-20261117',
                 'proof_sha256': row['proof_sha256'], 'scope': details,
                 'dependencies': dependencies, 'reference_records': list(refs),
                 'outcome': outcome}
        prior = {k: row.get(k, '') for k in ('own_check', 'check_outcome', 'depends_on', 'credit_checks')}
        if not any(e.get('event') == event['event'] for e in row.get('check_history', [])):
            row.setdefault('check_history', []).append({'event': 'prior-record-preserved', **prior})
            row['check_history'].append(event)
        row['dependency_closure'] = event
        row['check_outcome'] = outcome
        row['depends_on'] = dependencies
        events.append(event)

