mf = ROOT/'deliverables/code/cdp_audit/execution_manifest_final_certificates.json'
for rec in json.loads(mf.read_text()):
    for sid in program_map[Path(rec['source']).name]:
        by_id[sid].setdefault('program_checks', [])
        if not any(x.get('source')==rec['source'] for x in by_id[sid]['program_checks']):
            by_id[sid]['program_checks'].append({**rec, 'manifest':str(mf.relative_to(ROOT))})

for row in rows:
    if row['source_id']=='C.2.CR.2':
        row['credit_checks']=row['credit_checks'].replace('RRV original separately in progress.', 'RRV71 original proper relative duality pp261–268 subsequently opened; exact scope is retained in references_verified.json.')
    assert row['own_check']
    p=ROOT/row['extracted_file']
    text=p.read_text()
    candidates=[text]+[text[:m.start()] for m in re.finditer(r'\n\\subsection\{',text)]
    assert any(hashlib.sha256(t.encode()).hexdigest()==row['proof_sha256'] for t in candidates), row['source_id']
    row['extracted_file_sha256']=hashlib.sha256(p.read_bytes()).hexdigest()
    row['proof_hash_scope']='Full result block, with the following subsection heading omitted where present; extracted_file_sha256 separately hashes the entire extraction including that heading.'
(OUT/'result_audit.json').write_text(json.dumps(rows, ensure_ascii=False, indent=2)+'\n')
fields=list(dict.fromkeys(k for row in rows for k in row))
with (OUT/'result_audit.csv').open('w', newline='') as f:
    w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
    w.writerows({k:json.dumps(v,ensure_ascii=False) if isinstance(v,(dict,list)) else v for k,v in row.items()} for row in rows)
(OUT/'dependency_closure_events.json').write_text(json.dumps(events, ensure_ascii=False, indent=2)+'\n')
print('Persisted',len(events),'individually scoped closure events; preserved all239 source proof hashes.')
